# Generates test/scipy/test_stats_final_sobol.py with scipy 1.18.1.
import numpy as np, scipy.stats as st
from scipy.stats import uniform
from scipy.stats._sensitivity_analysis import f_ishigami
dists = [uniform(loc=-np.pi, scale=2 * np.pi)] * 3
r = st.sobol_indices(func=f_ishigami, n=1024, dists=dists, rng=np.random.default_rng(1))
def L(a): return repr([float(v) for v in np.ravel(a)])
o = ["# Copyright (C) 2026 the Typhon authors",
"# Expected values generated by test/scipy/gen_stats_final_sobol.py (scipy 1.18.1).",
"import numpy as np", "import scipy.stats as st", "from scipy.stats import uniform", "",
"def f(x):", "    return np.sin(x[0]) + 7 * np.sin(x[1]) ** 2 + 0.1 * (x[2] ** 4) * np.sin(x[0])", "",
"@test", "def test_sobol_indices():",
"    dists = [uniform(loc=-np.pi, scale=2 * np.pi), uniform(loc=-np.pi, scale=2 * np.pi), uniform(loc=-np.pi, scale=2 * np.pi)]",
"    r = st.sobol_indices(func=f, n=1024, dists=dists, rng=np.random.default_rng(1))",
f"    e1 = {L(r.first_order)}", f"    et = {L(r.total_order)}",
"    for i in range(3):", "        assert abs(float(r.first_order[i]) - e1[i]) < 1e-6", "        assert abs(float(r.total_order[i]) - et[i]) < 1e-6"]
print("\n".join(o))
